const DB_KEY='forgepro_local_v1';
const defaultDB={settings:{shopName:'ورشة بو منصور للحدادة والألمنيوم واليو بي في سي',phone:'5583 0254',address:'',currency:'ر.ق',tax:0},customers:[],projects:[],quotes:[],production:[],inventory:[],purchases:[],installations:[],invoices:[],expenses:[],suppliers:[]};
let db=loadDB(),currentPage='dashboard',toastTimer;
function loadDB(){try{const saved=JSON.parse(localStorage.getItem(DB_KEY)||'{}');const out={...structuredClone(defaultDB),...saved};out.settings={...structuredClone(defaultDB.settings),...(saved.settings||{})};if(!out.settings.shopName||out.settings.shopName==='ورشة الحدادة والألمنيوم')out.settings.shopName=defaultDB.settings.shopName;if(!out.settings.phone)out.settings.phone='5583 0254';return out}catch(e){return structuredClone(defaultDB)}}
function saveDB(){localStorage.setItem(DB_KEY,JSON.stringify(db));}
function uid(prefix){return prefix+'-'+Date.now().toString().slice(-8)+'-'+Math.floor(Math.random()*90+10)}
function money(v){return (Number(v)||0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})+' '+(db.settings.currency||'ر.ق')}
function quoteNumber(v){const n=Number(v)||0;return n===0?'':n.toLocaleString('en-US',{minimumFractionDigits:0,maximumFractionDigits:2})}
function dateNow(){return new Date().toISOString().slice(0,10)}
function nextQuoteCode(){return 'QT-'+String(Math.max(0,...db.quotes.map(x=>Number(String(x.code||'').match(/(\d+)$/)?.[1]||0)))+1).padStart(5,'0')}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2600)}
function pageTitle(p){return ({dashboard:'لوحة التحكم',customers:'العملاء',projects:'المشاريع والقياسات',quotes:'عروض الأسعار',production:'أوامر التصنيع',inventory:'المخزون والمواد',purchases:'المشتريات والموردون',installations:'التركيب والتسليم',invoices:'الفواتير والدفعات',expenses:'المصروفات',reports:'التقارير',settings:'الإعدادات والنسخ الاحتياطي'})[p]||'ForgePro'}
function setPage(p){currentPage=p;document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===p));document.getElementById('pageTitle').textContent=pageTitle(p);document.getElementById('sidebar').classList.remove('open');render()}
function head(title,desc,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p>${desc}</p></div><div class="head-actions">${actions}</div></div>`}
function btn(label,act,kind='btn-primary'){return `<button class="btn ${kind}" onclick="${act}">${label}</button>`}
function stat(label,value,icon,foot=''){return `<div class="stat-card"><div class="stat-top"><span>${label}</span><div class="stat-icon">${icon}</div></div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div></div>`}
function empty(text='لا توجد بيانات حتى الآن'){return `<div class="empty-state"><div class="empty-icon">◌</div>${text}</div>`}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows||''}</tbody></table></div>`}
function badge(status){let cls='';if(/مكتمل|مسدد|معتمد|مستلم/.test(status))cls='green';else if(/متأخر|ملغي|مرفوض/.test(status))cls='red';else if(/انتظار|قيد|جديد|غير مسدد/.test(status))cls='orange';else if(/جاهز/.test(status))cls='blue';return `<span class="badge ${cls}">${esc(isEnglish()?(EN[status]||status):(AR[status]||status||'—'))}</span>`}
function customerName(id){return db.customers.find(x=>x.id===id)?.name||(isEnglish()?'Unspecified Customer':'عميل غير محدد')}
function projectName(id){return db.projects.find(x=>x.id===id)?.name||(isEnglish()?'Unspecified Project':'مشروع غير محدد')}

