const AR=Object.fromEntries(Object.entries(EN).map(([a,b])=>[b,a]));
function isEnglish(){return db.settings?.language==='en'}
function setLanguage(lang){db.settings.language=lang==='en'?'en':'ar';saveDB();render();applyLocale();}
function applyLocale(){const en=isEnglish(),dict=en?EN:AR,root=document.documentElement;root.lang=en?'en':'ar';root.dir=en?'ltr':'rtl';document.body.classList.toggle('english-ui',en);const title=document.getElementById('pageTitle');if(title)title.textContent=dict[pageTitle(currentPage)]||pageTitle(currentPage);const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let n;while(n=walker.nextNode()){const raw=n.nodeValue,trim=raw.trim();if(dict[trim])n.nodeValue=raw.replace(trim,dict[trim]);}document.querySelectorAll('[placeholder],[aria-label],[title]').forEach(el=>['placeholder','aria-label','title'].forEach(a=>{const v=el.getAttribute(a);if(v&&dict[v])el.setAttribute(a,dict[v]);}));}

function render(){const el=document.getElementById('content');const map={dashboard:dashboardPage,customers:customersPage,projects:projectsPage,quotes:quotesPage,production:productionPage,inventory:inventoryPage,purchases:purchasesPage,installations:installationsPage,invoices:invoicesPage,expenses:expensesPage,reports:reportsPage,settings:settingsPage};el.innerHTML=(map[currentPage]||dashboardPage)();applyLocale()}
function dashboardPage(){
 const open=db.production.filter(x=>!['مكتمل','ملغي'].includes(x.status)).length, unpaid=db.invoices.reduce((s,x)=>s+Math.max(0,(+x.total||0)-(+x.paid||0)),0), stockLow=db.inventory.filter(x=>(+x.qty||0)<=(+x.min||0)).length, revenue=db.invoices.reduce((s,x)=>s+(+x.paid||0),0), expenses=db.expenses.reduce((s,x)=>s+(+x.amount||0),0);
 const recent=[...db.projects].slice(-5).reverse().map(p=>`<tr><td><span class="primary-cell">${esc(p.name)}</span><span class="sub-cell">${esc(p.code||p.id)}</span></td><td>${esc(customerName(p.customerId))}</td><td>${esc(p.type||'—')}</td><td>${badge(p.status||'جديد')}</td><td>${money(p.total)}</td></tr>`).join('');
 return head('مرحبًا بك في ForgePro','نظرة عامة على أداء الورشة وحالة المشاريع اليوم',btn('＋ مشروع جديد',"openForm('project')"))+
 `<div class="stats-grid">${stat('المبالغ المحصلة',money(revenue),'↗','إجمالي الدفعات المسجلة')}${stat('أوامر التصنيع المفتوحة',open,'⚒','تحتاج إلى متابعة')}${stat('المبالغ المستحقة',money(unpaid),'ر.ق','حسب الفواتير المسجلة')}${stat('تنبيهات المخزون',stockLow,'▥','أصناف عند الحد الأدنى أو أقل')}</div>
 <div class="dashboard-grid"><div><div class="panel"><div class="panel-head"><div><h3>أحدث المشاريع</h3><p>آخر المشاريع المسجلة في النظام</p></div>${btn('عرض الكل',"setPage('projects')",'btn-light btn-small')}</div>${recent?table(['المشروع','العميل','نوع العمل','الحالة','القيمة'],recent):empty('أضف أول مشروع لتبدأ إدارة أعمال الورشة')}</div>
 <div class="panel"><div class="panel-head"><div><h3>إجراءات سريعة</h3><p>ابدأ العمل دون التنقل بين الأقسام</p></div></div><div class="panel-body"><div class="quick-grid"><button class="quick-tile" onclick="openForm('customer')"><span>♙</span><b>إضافة عميل</b><small>تسجيل عميل جديد</small></button><button class="quick-tile" onclick="openForm('project')"><span>▤</span><b>مشروع جديد</b><small>تسجيل القياسات والتكلفة</small></button><button class="quick-tile" onclick="openForm('inventory')"><span>▥</span><b>إضافة مادة</b><small>تحديث المخزون</small></button><button class="quick-tile" onclick="openForm('quote')"><span>▧</span><b>عرض سعر</b><small>إنشاء تسعير للعميل</small></button><button class="quick-tile" onclick="openForm('production')"><span>⚒</span><b>أمر تصنيع</b><small>بدء متابعة الإنتاج</small></button><button class="quick-tile" onclick="openForm('invoice')"><span>▣</span><b>فاتورة جديدة</b><small>إنشاء فاتورة للعميل</small></button></div></div></div></div>
 <div><div class="panel"><div class="panel-head"><div><h3>حالة الإنتاج</h3><p>توزيع أوامر التصنيع الحالية</p></div></div><div class="panel-body">${productionBars()}</div></div><div class="panel"><div class="panel-head"><div><h3>ملخص مالي</h3><p>المبالغ المسجلة في النظام</p></div></div><div class="panel-body"><div class="bar-row"><div class="bar-meta"><span>المقبوضات</span><span>${money(revenue)}</span></div><div class="progress"><span style="width:${Math.min(100,revenue/(revenue+expenses+1)*100)}%"></span></div></div><div class="bar-row"><div class="bar-meta"><span>المصروفات</span><span>${money(expenses)}</span></div><div class="progress"><span style="width:${Math.min(100,expenses/(revenue+expenses+1)*100)}%;background:#d65353"></span></div></div><div class="bar-row"><div class="bar-meta"><span>مستحقات العملاء</span><span>${money(unpaid)}</span></div><div class="progress"><span style="width:${Math.min(100,unpaid/(revenue+unpaid+1)*100)}%;background:#477bd4"></span></div></div></div></div><div class="notice">تذكير: خذ نسخة احتياطية دورية من صفحة الإعدادات، لأن بيانات هذا الإصدار محفوظة على المتصفح والجهاز الحالي.</div></div></div>`
}
function productionBars(){if(!db.production.length)return empty('لا توجد أوامر تصنيع');const statuses=['جديد','جاهز للتصنيع','قيد التصنيع','قيد التشطيب','تحت الفحص','جاهز للتركيب','مكتمل'];return statuses.map((s,i)=>{let n=db.production.filter(x=>x.status===s).length;return `<div class="bar-row"><div class="bar-meta"><span>${s}</span><span>${n}</span></div><div class="progress"><span style="width:${n/Math.max(1,db.production.length)*100}%;background:${['#d5a04c','#477bd4','#e5a23b','#9b79ce','#2c9c80','#4d8ed8','#169b72'][i]}"></span></div></div>`}).join('')}
function customersPage(){let rows=db.customers.slice().reverse().map(c=>`<tr><td><span class="primary-cell">${esc(c.name)}</span><span class="sub-cell">${esc(c.code||'')}</span></td><td>${esc(c.phone||'—')}</td><td>${esc(c.type||'فرد')}</td><td>${esc(c.address||'—')}</td><td>${db.projects.filter(p=>p.customerId===c.id).length}</td><td>${btn('تعديل',`editItem('customer','${c.id}')`,'btn-light btn-small')} ${btn('حذف',`deleteItem('customers','${c.id}')`,'btn-danger btn-small')}</td></tr>`).join('');return head('العملاء','إدارة بيانات العملاء والمقاولين وسجل مشاريعهم',btn('＋ إضافة عميل',"openForm('customer')"))+`<div class="panel"><div class="panel-body"><div class="search-row"><input class="field search-input" placeholder="ابحث بالاسم أو الهاتف..." oninput="filterRows(this,0)"><span class="badge">${db.customers.length} عميل</span></div><div id="customerTable">${rows?table(['العميل','الهاتف','نوع العميل','العنوان','المشاريع','الإجراءات'],rows):empty('لا يوجد عملاء. أضف أول عميل.')}</div></div></div>`}
function projectsPage(){let rows=db.projects.slice().reverse().map(p=>`<tr><td><span class="primary-cell">${esc(p.name)}</span><span class="sub-cell">${esc(p.code||p.id)}</span></td><td>${esc(customerName(p.customerId))}</td><td>${esc(p.type||'—')}</td><td>${p.width&&p.height?`${p.width} × ${p.height} ${esc(p.unit||'سم')}`:'متعدد'}</td><td>${esc(p.qty||1)}</td><td>${badge(p.status||'جديد')}</td><td>${money(p.total)}</td><td>${btn('تعديل',`editItem('project','${p.id}')`,'btn-light btn-small')} ${btn('حذف',`deleteItem('projects','${p.id}')`,'btn-danger btn-small')}</td></tr>`).join('');return head('المشاريع والقياسات','تسجيل أعمال الحدادة والألمنيوم وحساب المساحات والكميات',btn('＋ مشروع جديد',"openForm('project')"))+`<div class="panel"><div class="panel-body"><div class="search-row"><input class="field search-input" placeholder="ابحث باسم المشروع أو العميل..." oninput="filterRows(this,0)"><span class="badge">${db.projects.length} مشروع</span></div>${rows?table(['المشروع','العميل','نوع العمل','المقاس','العدد','الحالة','القيمة','الإجراءات'],rows):empty('لا توجد مشاريع مسجلة بعد.')}</div></div>`}
function quotesPage(){
 const quotes=db.quotes.slice().reverse();
 const count=status=>quotes.filter(q=>(q.status||'مسودة')===status).length;
 const rows=quotes.map(q=>{
  const status=q.status||'مسودة';
  const work=Object.keys(q).filter(k=>/^title\d*$/.test(k)).sort((a,b)=>{const n=x=>x==='title'?1:Number(x.slice(5));return n(a)-n(b)}).map(k=>q[k]).filter(Boolean).join('، ');
  const searchText=[q.code,customerName(q.customerId),work,status,q.date].join(' ').toLowerCase();
  const statusAction=status==='معتمد'?btn('إلغاء الاعتماد',`cancelQuoteApproval('${q.id}')`,'btn-light btn-small'):btn('اعتماد',`approveQuote('${q.id}')`,'btn-approve btn-small');
  return `<tr class="quote-row" data-status="${esc(status)}" data-search="${esc(searchText)}">
   <td><span class="primary-cell quote-code">${esc(q.code||'—')}</span><span class="sub-cell">${esc(q.date||'—')}</span></td>
   <td><span class="primary-cell">${esc(customerName(q.customerId))}</span><span class="sub-cell quote-work-summary">${esc(work||'—')}</span></td>
   <td>${badge(status)}</td><td class="quote-amount">${money(q.total)}</td>
   <td><div class="quote-row-actions">${btn('تعديل',`editItem('quote','${q.id}')`,'btn-primary btn-small')} <button class="btn btn-light btn-small" onclick="exportDocument('quote','${q.id}')">PDF</button> ${statusAction}<button class="quote-delete" title="حذف العرض" aria-label="حذف العرض" onclick="deleteItem('quotes','${q.id}')">حذف</button></div></td>
  </tr>`;
 }).join('');
 return head('عروض الأسعار','إنشاء العروض ومراجعتها ومتابعة حالتها من مكان واحد',btn('＋ عرض سعر جديد',"openForm('quote')"))+
 `<div class="quote-overview"><span>كل العروض <b>${quotes.length}</b></span><i></i><span>مسودات <b>${count('مسودة')}</b></span><i></i><span>معتمدة <b>${count('معتمد')}</b></span></div>
 <div class="panel quote-list-panel"><div class="panel-body"><div class="quote-toolbar"><div class="quote-search-wrap"><span>⌕</span><input id="quoteSearch" class="field" placeholder="ابحث برقم العرض أو اسم العميل أو العمل" oninput="filterQuoteCards()"></div><select id="quoteStatusFilter" class="field quote-status-filter" onchange="filterQuoteCards()"><option value="">كل الحالات</option><option>مسودة</option><option>مرسل للعميل</option><option>معتمد</option><option>مرفوض</option></select><span class="quote-result-count" id="quoteResultCount">${quotes.length} عرض</span></div>
 ${rows?`<div class="table-wrap quote-table-wrap"><table class="quote-list-table"><thead><tr><th>رقم العرض / التاريخ</th><th>العميل / تفاصيل العمل</th><th>الحالة</th><th>الإجمالي</th><th>الإجراءات</th></tr></thead><tbody id="quoteCardGrid">${rows}</tbody></table></div><div class="empty-state quote-no-results" id="quoteNoResults" hidden>لا توجد عروض مطابقة للبحث.</div>`:empty('لا توجد عروض أسعار مسجلة. أنشئ أول عرض للبدء.')}</div></div>`
}
function filterQuoteCards(){const search=(document.getElementById('quoteSearch')?.value||'').trim().toLowerCase(),status=document.getElementById('quoteStatusFilter')?.value||'';const rows=[...document.querySelectorAll('.quote-row')];let shown=0;rows.forEach(row=>{const match=(!search||(row.dataset.search||'').includes(search))&&(!status||row.dataset.status===status);row.hidden=!match;if(match)shown++});const count=document.getElementById('quoteResultCount');if(count)count.textContent=`${shown} عرض`;const empty=document.getElementById('quoteNoResults');if(empty)empty.hidden=shown!==0||rows.length===0}

function productionPage(){let rows=db.production.slice().reverse().map(p=>`<tr><td><span class="primary-cell">${esc(p.code)}</span></td><td>${esc(projectName(p.projectId))}</td><td>${esc(p.stage||'تصنيع')}</td><td>${esc(p.worker||'—')}</td><td>${esc(p.due||'—')}</td><td>${badge(p.status||'جديد')}</td><td><select class="field" style="min-width:140px;padding:6px" onchange="changeStatus('production','${p.id}',this.value)">${['جديد','جاهز للتصنيع','قيد التصنيع','قيد التشطيب','تحت الفحص','جاهز للتركيب','مكتمل','ملغي'].map(s=>`<option ${s===p.status?'selected':''}>${s}</option>`).join('')}</select></td></tr>`).join('');return head('أوامر التصنيع','متابعة مراحل القص والتجميع والتشطيب والفحص',btn('＋ أمر تصنيع',"openForm('production')"))+`<div class="panel"><div class="panel-body">${rows?table(['رقم الأمر','المشروع','المرحلة','المسؤول','موعد التسليم','الحالة','تحديث الحالة'],rows):empty('لا توجد أوامر تصنيع. أنشئ أمرًا من مشروع قائم.')}</div></div>`}
function inventoryPage(){let rows=db.inventory.slice().reverse().map(i=>`<tr><td><span class="primary-cell">${esc(i.name)}</span><span class="sub-cell">${esc(i.code||'')}</span></td><td>${esc(i.category||'مواد خام')}</td><td>${esc(i.unit||'قطعة')}</td><td>${esc(i.qty)}</td><td>${esc(i.min||0)}</td><td>${money(i.cost)}</td><td>${money((+i.qty||0)*(+i.cost||0))}</td><td>${(+i.qty||0)<=(+i.min||0)?badge('مخزون منخفض'):badge('متوفر')}</td><td>${btn('تعديل',`editItem('inventory','${i.id}')`,'btn-light btn-small')} ${btn('حركة',`stockMovement('${i.id}')`,'btn-primary btn-small')}</td></tr>`).join('');return head('المخزون والمواد','إدارة القطاعات والحديد والزجاج والإكسسوارات والهالك',btn('＋ إضافة مادة',"openForm('inventory')"))+`<div class="stats-grid">${stat('عدد الأصناف',db.inventory.length,'▥')}${stat('قيمة المخزون',money(db.inventory.reduce((s,x)=>s+(+x.qty||0)*(+x.cost||0),0)),'ر.ق')}${stat('أصناف منخفضة',db.inventory.filter(x=>(+x.qty||0)<=(+x.min||0)).length,'!')}${stat('وحدات المخزون',db.inventory.reduce((s,x)=>s+(+x.qty||0),0).toLocaleString('en-US'),'▤')}</div><div class="panel"><div class="panel-body"><div class="search-row"><input class="field search-input" placeholder="ابحث عن مادة أو كود..." oninput="filterRows(this,0)"></div>${rows?table(['الصنف','الفئة','الوحدة','الكمية','حد التنبيه','تكلفة الوحدة','قيمة المخزون','الحالة','الإجراءات'],rows):empty('أضف المواد الخام والأصناف لتبدأ متابعة المخزون.')}</div></div>`}
function purchasesPage(){let rows=db.purchases.slice().reverse().map(p=>`<tr><td class="primary-cell">${esc(p.code)}</td><td>${esc(p.supplier||'—')}</td><td>${esc(p.item||'—')}</td><td>${esc(p.qty)}</td><td>${money(p.total)}</td><td>${esc(p.date||'—')}</td><td>${badge(p.status||'مستلم')}</td></tr>`).join('');return head('المشتريات والموردون','تسجيل مشتريات المواد الخام وتتبع الموردين',btn('＋ تسجيل شراء',"openForm('purchase')"))+`<div class="panel"><div class="panel-body">${rows?table(['رقم الشراء','المورد','الصنف','الكمية','الإجمالي','التاريخ','الحالة'],rows):empty('لا توجد عمليات شراء مسجلة.')}</div></div>`}
function installationsPage(){let rows=db.installations.slice().reverse().map(i=>`<tr><td class="primary-cell">${esc(i.code)}</td><td>${esc(projectName(i.projectId))}</td><td>${esc(i.location||'—')}</td><td>${esc(i.team||'—')}</td><td>${esc(i.date||'—')}</td><td>${badge(i.status||'مجدول')}</td><td>${btn('تحديث',`editItem('installation','${i.id}')`,'btn-light btn-small')}</td></tr>`).join('');return head('التركيب والتسليم','جدولة فرق التركيب وتوثيق إنجاز المشاريع في الموقع',btn('＋ موعد تركيب',"openForm('installation')"))+`<div class="panel"><div class="panel-body">${rows?table(['رقم العملية','المشروع','الموقع','الفريق','التاريخ','الحالة','الإجراءات'],rows):empty('لا توجد عمليات تركيب مجدولة.')}</div></div>`}
function invoicesPage(){let rows=db.invoices.slice().reverse().map(i=>`<tr><td class="primary-cell">${esc(i.code)}</td><td>${esc(customerName(i.customerId))}</td><td>${esc(i.date||'—')}</td><td>${money(i.total)}</td><td>${(+i.paid||0)>0?money(i.paid):'—'}</td><td>${money(Math.max(0,(+i.total||0)-(+i.paid||0)))}</td><td>${badge((+i.paid||0)>=(+i.total||0)?'مسدد':(+i.paid||0)>0?'مدفوع جزئيًا':'غير مسدد')}</td><td>${btn('تعديل',`editItem('invoice','${i.id}')`,'btn-light btn-small')} <button class="btn btn-light btn-small" onclick="exportDocument('invoice','${i.id}')">PDF</button> ${btn('تسجيل دفعة',`payInvoice('${i.id}')`,'btn-primary btn-small')}</td></tr>`).join('');return head('الفواتير والدفعات','متابعة قيمة الفواتير والتحصيلات والأرصدة المتبقية',btn('＋ فاتورة جديدة',"openForm('invoice')"))+`<div class="panel"><div class="panel-body">${rows?table(['رقم الفاتورة','العميل','التاريخ','الإجمالي','المدفوع','المتبقي','الحالة','الإجراءات'],rows):empty('لا توجد فواتير. يمكنك تسجيل فاتورة أو دفعة.')}</div></div>`}
function expensesPage(){let rows=db.expenses.slice().reverse().map(e=>`<tr><td class="primary-cell">${esc(e.title)}</td><td>${esc(e.category||'عام')}</td><td>${money(e.amount)}</td><td>${esc(e.date||'—')}</td><td>${esc(e.note||'—')}</td><td>${btn('حذف',`deleteItem('expenses','${e.id}')`,'btn-danger btn-small')}</td></tr>`).join('');return head('المصروفات','تسجيل النفقات التشغيلية ومتابعة تكاليف الورشة',btn('＋ مصروف جديد',"openForm('expense')"))+`<div class="stats-grid">${stat('إجمالي المصروفات',money(db.expenses.reduce((s,e)=>s+(+e.amount||0),0)),'↗')}${stat('عدد القيود',db.expenses.length,'▤')}</div><div class="panel"><div class="panel-body">${rows?table(['المصروف','التصنيف','المبلغ','التاريخ','ملاحظات','الإجراءات'],rows):empty('لا توجد مصروفات مسجلة.')}</div></div>`}
function reportsPage(){let sales=db.invoices.reduce((s,x)=>s+(+x.total||0),0),paid=db.invoices.reduce((s,x)=>s+(+x.paid||0),0),cost=db.projects.reduce((s,x)=>s+(+x.cost||0),0),expenses=db.expenses.reduce((s,x)=>s+(+x.amount||0),0);return head('التقارير','ملخصات تشغيلية ومالية من البيانات المحفوظة',btn('طباعة التقرير','window.print()','btn-light'))+`<div class="stats-grid">${stat('إجمالي الفواتير',money(sales),'▣')}${stat('إجمالي المقبوضات',money(paid),'↗')}${stat('تكاليف المشاريع المسجلة',money(cost),'⚒')}${stat('المصروفات',money(expenses),'↘')}</div><div class="two-col"><div class="panel"><div class="panel-head"><h3>ملخص المشاريع</h3></div>${table(['المؤشر','القيمة'],`<tr><td>إجمالي المشاريع</td><td>${db.projects.length}</td></tr><tr><td>المشاريع المكتملة</td><td>${db.projects.filter(x=>x.status==='مكتمل').length}</td></tr><tr><td>أوامر التصنيع</td><td>${db.production.length}</td></tr><tr><td>عمليات التركيب</td><td>${db.installations.length}</td></tr>`)}</div><div class="panel"><div class="panel-head"><h3>ملخص مالي</h3></div>${table(['المؤشر','القيمة'],`<tr><td>المبالغ المستحقة</td><td>${money(Math.max(0,sales-paid))}</td></tr><tr><td>تكلفة المخزون الحالية</td><td>${money(db.inventory.reduce((s,x)=>s+(+x.qty||0)*(+x.cost||0),0))}</td></tr><tr><td>المصروفات المسجلة</td><td>${money(expenses)}</td></tr><tr><td>صافي تقديري قبل تسويات أخرى</td><td>${money(paid-expenses-cost)}</td></tr>`)}</div></div><div class="notice">التقارير تعتمد على البيانات التي أدخلتها. صافي الربح هنا تقديري، ولا يُعد قوائم مالية معتمدة.</div>`}
function settingsPage(){return head('الإعدادات والنسخ الاحتياطي','إدارة بيانات الورشة وحفظ نسخة من قاعدة البيانات')+`<div class="settings-card language-card"><h3>لغة النظام / Interface Language</h3><p>اختر لغة واجهة البرنامج. سيتم حفظ اختيارك على هذا الجهاز. / Choose the application language. Your preference is saved on this device.</p><label for="appLanguage">اللغة / Language</label><select id="appLanguage" class="field" onchange="setLanguage(this.value)"><option value="ar" ${!isEnglish()?'selected':''}>العربية</option><option value="en" ${isEnglish()?'selected':''}>English</option></select></div><div class="two-col"><div class="settings-card"><h3>بيانات الورشة</h3><p>تظهر هذه البيانات في المستندات المطبوعة.</p><form id="settingsForm" onsubmit="saveSettings(event)"><div class="form-grid"><div class="full"><label>اسم الورشة</label><input class="field" name="shopName" value="${esc(db.settings.shopName)}" required></div><div><label>رقم الهاتف</label><input class="field" name="phone" value="${esc(db.settings.phone)}"></div><div><label>العملة</label><input class="field" name="currency" value="${esc(db.settings.currency)}"></div><div class="full"><label>العنوان</label><input class="field" name="address" value="${esc(db.settings.address)}"></div><div><label>الضريبة %</label><input class="field" type="number" min="0" max="100" step=".01" name="tax" value="${esc(db.settings.tax)}"></div></div><div class="form-actions"><button class="btn btn-primary">حفظ الإعدادات</button></div></form></div><div><div class="settings-card"><h3>النسخ الاحتياطي</h3><p>صدّر كل بياناتك إلى ملف JSON، ثم احتفظ به على وحدة تخزين خارجية أو مكان آمن.</p><button class="btn btn-primary" onclick="exportBackup()">⬇ تنزيل نسخة احتياطية</button><hr style="border:0;border-top:1px solid #edf1f5;margin:18px 0"><label>استعادة نسخة احتياطية</label><input class="field" type="file" id="backupFile" accept=".json,application/json"><div class="form-actions"><button class="btn btn-light" onclick="importBackup()">استعادة البيانات</button></div></div><div class="settings-card"><h3>تصدير البيانات</h3><p>يمكنك تصدير الجداول الأساسية بصيغة CSV وفتحها في برامج الجداول.</p><button class="btn btn-light" onclick="exportCSV('customers')">تصدير العملاء CSV</button> <button class="btn btn-light" onclick="exportCSV('projects')">تصدير المشاريع CSV</button></div><div class="settings-card"><h3>إدارة البيانات</h3><p>حذف البيانات لا يمكن التراجع عنه. صدّر نسخة احتياطية قبل المتابعة.</p><button class="btn btn-danger" onclick="resetData()">إعادة ضبط جميع البيانات</button></div></div></div>`}
function options(items,selected){return `<option value="">اختر...</option>`+items.map(x=>`<option value="${esc(x.id)}" ${x.id===selected?'selected':''}>${esc(x.name||x.code||x.title)}</option>`).join('')}
const schemas={
 customer:{title:'إضافة عميل',collection:'customers',prefix:'CUS',fields:[['name','اسم العميل','text',1],['phone','رقم الهاتف','tel'],['type','نوع العميل','select',['فرد','شركة','مقاول']],['address','العنوان / موقع العمل','text'],['note','ملاحظات','textarea']]},
 project:{title:'مشروع جديد',collection:'projects',prefix:'PRJ',fields:[['name','اسم المشروع','text',1],['customerId','العميل','selectCustomers',1],['type','نوع العمل','select',['باب ألمنيوم','شبابيك ألمنيوم','واجهة زجاجية','مطبخ ألمنيوم','بوابة حديد','درابزين','مظلة','هيكل معدني','أعمال أخرى']],['width','العرض','number'],['height','الارتفاع','number'],['unit','وحدة القياس','select',['سم','مم','متر']],['qty','العدد','number',1],['unitPrice','سعر الوحدة','number'],['total','قيمة البيع','number'],['cost','التكلفة التقديرية','number'],['status','الحالة','select',['جديد','بانتظار القياسات','بانتظار موافقة العميل','قيد التصنيع','جاهز للتركيب','مكتمل']],['due','موعد التسليم','date'],['note','ملاحظات / مواصفات','textarea']]},
 quote:{title:'إنشاء عرض سعر',collection:'quotes',prefix:'QT',fields:[['customerEntry','اختر اسم العميل','customerEntry'],['date','تاريخ عرض السعر','date',1],['code','رقم العرض','text',1],['extra','تكاليف إضافية','number'],['discount','الخصم','number'],['status','الحالة','select',['مسودة','مرسل للعميل','معتمد','مرفوض']],['note','المواصفات والشروط','textarea']]},
 production:{title:'إنشاء أمر تصنيع',collection:'production',prefix:'FAB',fields:[['projectId','المشروع','selectProjects',1],['stage','مرحلة العمل','select',['تجهيز المواد','القص','التشغيل والتخريم','التجميع','اللحام','التشطيب والدهان','تركيب الزجاج والإكسسوارات','الفحص النهائي']],['worker','الفني / المسؤول','text'],['due','موعد التسليم','date'],['status','الحالة','select',['جديد','جاهز للتصنيع','قيد التصنيع','قيد التشطيب','تحت الفحص','جاهز للتركيب','مكتمل','ملغي']],['note','ملاحظات التصنيع','textarea']]},
 inventory:{title:'إضافة مادة للمخزون',collection:'inventory',prefix:'STK',fields:[['name','اسم المادة / الصنف','text',1],['category','الفئة','select',['قطاع ألمنيوم','حديد','زجاج','إكسسوارات','مواد لحام','دهان وتشطيب','أدوات','أخرى']],['unit','الوحدة','select',['عود','متر','متر مربع','قطعة','كيلوغرام','علبة','لتر']],['qty','الكمية الحالية','number',1],['min','حد التنبيه','number'],['cost','تكلفة الوحدة','number'],['code','كود الصنف','text'],['note','موقع التخزين / ملاحظات','textarea']]},
 purchase:{title:'تسجيل عملية شراء',collection:'purchases',prefix:'PUR',fields:[['supplier','اسم المورد','text',1],['item','الصنف المشترى','text',1],['qty','الكمية','number',1],['unitCost','تكلفة الوحدة','number',1],['date','تاريخ الشراء','date'],['status','الحالة','select',['طلب شراء','مستلم','مرتجع']],['note','ملاحظات / رقم الفاتورة','textarea']]},
 installation:{title:'جدولة عملية تركيب',collection:'installations',prefix:'INS',fields:[['projectId','المشروع','selectProjects',1],['location','الموقع','text',1],['team','فريق التركيب','text'],['date','تاريخ التركيب','date',1],['status','الحالة','select',['مجدول','قيد التنفيذ','مكتمل','مؤجل']],['note','ملاحظات','textarea']]},
 invoice:{title:'إنشاء فاتورة',collection:'invoices',prefix:'INV',fields:[['customerEntry','اختر اسم العميل','customerEntry'],['date','تاريخ الفاتورة','date',1],['code','رقم الفاتورة','text',1],['paid','المبلغ المدفوع','number'],['extra','تكاليف إضافية','number'],['discount','الخصم','number'],['note','المواصفات والشروط','textarea']]},
 expense:{title:'تسجيل مصروف',collection:'expenses',prefix:'EXP',fields:[['title','اسم المصروف','text',1],['category','التصنيف','select',['مواد','رواتب','إيجار','نقل','كهرباء ومياه','صيانة معدات','أدوات','إداري','أخرى']],['amount','المبلغ','number',1],['date','التاريخ','date',1],['note','ملاحظات / مرجع','textarea']]}
};
function quoteWorkRow(i,old={}){const titleKey=i===1?'title':`title${i}`,qtyKey=i===1?'qty':`qty${i}`,priceKey=i===1?'unitPrice':`unitPrice${i}`;return `<div class="quote-work-row full" data-work-row="${i}"><div class="quote-work-title"><div class="quote-work-row-head"><label for="${titleKey}">وصف العمل ${i}</label><div class="quote-work-actions"><button type="button" class="btn btn-light btn-small" title="تحريك لأعلى" onclick="moveQuoteWorkRow(this,-1)">↑</button><button type="button" class="btn btn-light btn-small" title="تحريك لأسفل" onclick="moveQuoteWorkRow(this,1)">↓</button></div></div><textarea class="field quote-description-input" id="${titleKey}" name="${titleKey}" rows="1" oninput="this.style.height='auto';this.style.height=this.scrollHeight+'px'" required placeholder="اكتب وصف العمل">${esc(old[titleKey]||'')}</textarea></div><div><label for="${qtyKey}">العدد</label><input class="field" id="${qtyKey}" name="${qtyKey}" type="number" inputmode="decimal" step="0.01" min="0.01" value="${esc(old[qtyKey]??(i===1?1:''))}" required></div><div><label for="${priceKey}">السعر</label><input class="field" id="${priceKey}" name="${priceKey}" type="number" inputmode="decimal" step="0.01" min="0" value="${esc(old[priceKey]??(i===1?0:''))}" required></div></div>`}
function reindexQuoteWorkRows(){const wrap=document.getElementById('quoteWorkRows');if(!wrap)return;[...wrap.querySelectorAll('[data-work-row]')].forEach((row,index)=>{const i=index+1;row.dataset.workRow=i;const titleKey=i===1?'title':`title${i}`,qtyKey=i===1?'qty':`qty${i}`,priceKey=i===1?'unitPrice':`unitPrice${i}`;const label=row.querySelector('.quote-work-title label'),ta=row.querySelector('textarea'),inputs=row.querySelectorAll('input');label.textContent=`وصف العمل ${i}`;label.htmlFor=titleKey;ta.id=titleKey;ta.name=titleKey;inputs[0].id=qtyKey;inputs[0].name=qtyKey;inputs[1].id=priceKey;inputs[1].name=priceKey;});}
function moveQuoteWorkRow(button,direction){const row=button.closest('[data-work-row]'),wrap=document.getElementById('quoteWorkRows');if(!row||!wrap)return;const sibling=direction<0?row.previousElementSibling:row.nextElementSibling;if(!sibling)return;if(direction<0)wrap.insertBefore(row,sibling);else wrap.insertBefore(sibling,row);reindexQuoteWorkRows();}
function addQuoteWorkRow(){const wrap=document.getElementById('quoteWorkRows');if(!wrap)return;const next=wrap.querySelectorAll('[data-work-row]').length+1;wrap.insertAdjacentHTML('beforeend',quoteWorkRow(next));reindexQuoteWorkRows();}
function openForm(type,id=null){let sc=schemas[type];if(!sc)return;let old=id?db[sc.collection].find(x=>x.id===id):null;let fields=sc.fields.map(f=>{let [name,label,kind,extra]=f;let value=old?.[name]??(name==='customerEntry'&&(type==='quote'||type==='invoice')?(db.customers.find(c=>c.id===old?.customerId)?.name||old?.customerName||''):name==='date'?dateNow():name==='code'&&type==='quote'?nextQuoteCode():name==='code'&&type==='invoice'?uid('INV'):name==='customerName'&&type==='quote'?'':name==='qty'?1:name==='unit'?'سم':name==='status'?(type==='project'?'جديد':type==='quote'?'مسودة':type==='production'?'جديد':type==='installation'?'مجدول':''):name==='paid'?0:'');let req=extra===1;let input='';if(kind==='customerEntry')input=`<input class="field" name="customerEntry" type="text" list="quoteCustomerNames" value="${esc(value)}" placeholder="اختر اسماً مسجلاً أو اكتب اسم عميل جديد" autocomplete="off"><datalist id="quoteCustomerNames">${db.customers.map(c=>`<option value="${esc(c.name||'')}"></option>`).join('')}</datalist>`;else if(kind==='selectCustomers')input=`<select class="field" name="${name}" ${req?'required':''}>${options(db.customers,value)}</select>`;else if(kind==='selectProjects')input=`<select class="field" name="${name}" ${req?'required':''}>${options(db.projects,value)}</select>`;else if(kind==='select')input=`<select class="field" name="${name}" ${req?'required':''}>${extra.map(s=>`<option ${s===value?'selected':''}>${s}</option>`).join('')}</select>`;else if(kind==='textarea')input=`<textarea class="field" rows="3" name="${name}">${esc(value)}</textarea>`;else input=`<input class="field" name="${name}" type="${kind}" value="${esc(value)}" ${req?'required':''} ${kind==='number'?'step="0.01" min="0"':''}>`;return `<div class="${kind==='textarea'?'full':''}"><label>${label}</label>${input}</div>`}).join('');if(type==='quote'||type==='invoice'){let count=1;for(let i=2;i<100;i++){if(old?.[`title${i}`]||old?.[`qty${i}`]||old?.[`unitPrice${i}`])count=i;}const rows=Array.from({length:count},(_,j)=>quoteWorkRow(j+1,old||{})).join('');const workBlock=`<div class="full quote-work-section"><div id="quoteWorkRows">${rows}</div><button class="btn btn-light quote-add-btn" type="button" onclick="addQuoteWorkRow()">＋ إضافة وصف عمل</button></div>`;const firstEnd=fields.indexOf('</div>')+6;fields=fields.slice(0,firstEnd)+workBlock+fields.slice(firstEnd);}document.getElementById('modal').innerHTML=`<div class="modal-head"><h2>${old?'تعديل':'إضافة'} ${sc.title.replace(/^(إضافة|إنشاء|تسجيل|جدولة) /,'')}</h2><button class="modal-close" onclick="closeModal()">×</button></div><form id="dataForm" onsubmit="saveForm(event,'${type}','${id||''}')"><div class="modal-body"><div class="form-grid">${fields}</div><p style="font-size:10px;color:#9aa6b1;margin:16px 0 0">* الحقول المطلوبة يجب تعبئتها قبل الحفظ.</p></div><div class="modal-footer"><button class="btn btn-primary" type="submit">حفظ البيانات</button><button class="btn btn-light" type="button" onclick="closeModal()">إلغاء</button></div></form>`;document.getElementById('modalBackdrop').classList.add('show');applyLocale();document.querySelectorAll('.quote-description-input').forEach(el=>{el.style.height='auto';el.style.height=el.scrollHeight+'px'})}
function closeModal(){document.getElementById('modalBackdrop').classList.remove('show')}
function parseNumeric(v){if(v===undefined||v===null)return 0;let s=String(v).trim().replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d)).replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d)).replace(/[٬,]/g,'').replace(/٫/g,'.').replace(/[^0-9.\-]/g,'');const n=Number(s);return Number.isFinite(n)?n:0}
function saveForm(e,type,id){e.preventDefault();const sc=schemas[type],fd=new FormData(e.target),obj={};for(const [k,v] of fd.entries())obj[k]=v.trim();for(const f of sc.fields){let k=f[0];if(f[2]==='number')obj[k]=parseNumeric(obj[k])}if(type==='project'){if(!obj.total&&obj.width&&obj.height)obj.total=(Number(obj.width)/100)*(Number(obj.height)/100)*Number(obj.qty||1)*Number(obj.unitPrice||0);if(!obj.total)obj.total=Number(obj.qty||1)*Number(obj.unitPrice||0)}if(type==='quote'){let subtotal=0;for(const k of Object.keys(obj)){const m=k.match(/^(?:qty|unitPrice)(\d*)$/);if(m){obj[k]=parseNumeric(obj[k])}}for(let i=1;i<100;i++){const titleKey=i===1?'title':`title${i}`,qtyKey=i===1?'qty':`qty${i}`,priceKey=i===1?'unitPrice':`unitPrice${i}`;if(obj[titleKey]!==undefined||obj[qtyKey]!==undefined||obj[priceKey]!==undefined)subtotal+=parseNumeric(obj[qtyKey])*parseNumeric(obj[priceKey])}obj.total=Math.max(0,subtotal+parseNumeric(obj.extra)-parseNumeric(obj.discount));const oldQuote=id?db.quotes.find(x=>x.id===id):null;obj.code=(obj.code||oldQuote?.code||nextQuoteCode()).trim();if(db.quotes.some(x=>x.id!==id&&String(x.code||'').toLowerCase()===obj.code.toLowerCase())){toast('رقم العرض مستخدم بالفعل، اختر رقماً آخر');return}obj.date=obj.date||oldQuote?.date||dateNow();const enteredCustomer=(obj.customerEntry||'').trim();delete obj.customerEntry;if(enteredCustomer){let customer=db.customers.find(c=>String(c.name||'').trim().toLowerCase()===enteredCustomer.toLowerCase());if(!customer){customer={id:uid('CUS'),code:uid('CUS'),name:enteredCustomer};db.customers.push(customer)}obj.customerId=customer.id}else{obj.customerId=''}if(id&&oldQuote?.status==='معتمد')obj.status='مسودة'}if(type==='purchase'){obj.total=Number(obj.qty||0)*Number(obj.unitCost||0);let item=db.inventory.find(x=>x.name===obj.item);if(obj.status==='مستلم'&&item){item.qty=Number(item.qty||0)+Number(obj.qty||0)}}if(type==='invoice'){let subtotal=0;for(const k of Object.keys(obj)){const m=k.match(/^(?:qty|unitPrice)(\d*)$/);if(m)obj[k]=parseNumeric(obj[k])}for(let i=1;i<100;i++){const qk=i===1?'qty':`qty${i}`,pk=i===1?'unitPrice':`unitPrice${i}`;if(obj[qk]!==undefined||obj[pk]!==undefined)subtotal+=parseNumeric(obj[qk])*parseNumeric(obj[pk])}obj.subtotal=subtotal;obj.total=Math.max(0,subtotal+parseNumeric(obj.extra)-parseNumeric(obj.discount))*(1+(Number(db.settings.tax||0)/100));obj.paid=Math.min(Number(obj.paid||0),obj.total);const oldInvoice=id?db.invoices.find(x=>x.id===id):null;obj.code=(obj.code||oldInvoice?.code||uid('INV')).trim();if(db.invoices.some(x=>x.id!==id&&String(x.code||'').toLowerCase()===obj.code.toLowerCase())){toast('رقم الفاتورة مستخدم بالفعل، اختر رقماً آخر');return}obj.date=obj.date||oldInvoice?.date||dateNow();const enteredCustomer=(obj.customerEntry||'').trim();delete obj.customerEntry;if(enteredCustomer){let customer=db.customers.find(c=>String(c.name||'').trim().toLowerCase()===enteredCustomer.toLowerCase());if(!customer){customer={id:uid('CUS'),code:uid('CUS'),name:enteredCustomer};db.customers.push(customer)}obj.customerId=customer.id}else obj.customerId=oldInvoice?.customerId||''}if(type==='customer')obj.code=id?(db.customers.find(x=>x.id===id)?.code):uid('CUS');if(type==='project')obj.code=id?(db.projects.find(x=>x.id===id)?.code):uid('PRJ');if(type==='production')obj.code=id?(db.production.find(x=>x.id===id)?.code):uid('FAB');if(type==='inventory')obj.code=obj.code||uid('STK');if(type==='installation')obj.code=id?(db.installations.find(x=>x.id===id)?.code):uid('INS');if(type==='purchase')obj.code=id?(db.purchases.find(x=>x.id===id)?.code):uid('PUR');obj.id=id||uid(type.toUpperCase());if(!obj.date&&['expense','invoice','purchase','installation'].includes(type))obj.date=dateNow();if(id){let ix=db[sc.collection].findIndex(x=>x.id===id);if(ix>=0)db[sc.collection][ix]={...db[sc.collection][ix],...obj}}else db[sc.collection].push(obj);saveDB();closeModal();render();toast('تم حفظ البيانات بنجاح')}
function editItem(type,id){if(type==='installation'){openForm(type,id);return}openForm(type,id)}
function deleteItem(collection,id){if(!confirm('هل أنت متأكد من حذف هذا السجل؟'))return;db[collection]=db[collection].filter(x=>x.id!==id);saveDB();render();toast('تم حذف السجل')}
function changeStatus(collection,id,status){const x=db[collection].find(x=>x.id===id);if(x){x.status=status;saveDB();toast('تم تحديث الحالة');render()}}
function filterRows(input,col){const table=input.closest('.panel').querySelector('tbody');if(!table)return;let q=input.value.toLowerCase();[...table.rows].forEach(r=>r.style.display=r.cells[col]?.innerText.toLowerCase().includes(q)?'':'none')}
function approveQuote(id){let q=db.quotes.find(x=>x.id===id);if(!q)return;if(q.status==='معتمد'){toast('عرض السعر معتمد بالفعل');return}if(!confirm('هل تريد اعتماد عرض السعر؟'))return;q.status='معتمد';if(!db.projects.some(p=>p.quoteId===id)){const firstTitle=q.title||'عمل حسب عرض السعر';db.projects.push({id:uid('PRJ'),code:uid('PRJ'),name:firstTitle,customerId:q.customerId,type:'عمل حسب عرض السعر',qty:q.qty||1,unitPrice:q.unitPrice||0,total:q.total,cost:0,status:'جديد',quoteId:id,due:''})}saveDB();render();toast('تم اعتماد العرض وإنشاء مشروع مرتبط')}
function cancelQuoteApproval(id){const q=db.quotes.find(x=>x.id===id);if(!q)return;if(q.status!=='معتمد'){toast('عرض السعر غير معتمد');return}if(!confirm('هل تريد إلغاء اعتماد عرض السعر؟ سيعود إلى حالة «مسودة».'))return;q.status='مسودة';const linked=db.projects.filter(p=>p.quoteId===id);linked.forEach(p=>{if(p.status==='جديد')p.status='ملغي'});saveDB();render();toast(linked.some(p=>p.status!=='ملغي')?'تم إلغاء اعتماد العرض؛ تُرك المشروع الذي بدأ العمل عليه دون تغيير.':'تم إلغاء اعتماد العرض وإلغاء المشروع المرتبط الذي لم يبدأ العمل عليه.')}
function stockMovement(id){let x=db.inventory.find(x=>x.id===id);if(!x)return;document.getElementById('modal').innerHTML=`<div class="modal-head"><h2>حركة مخزون — ${esc(x.name)}</h2><button class="modal-close" onclick="closeModal()">×</button></div><form onsubmit="applyStock(event,'${id}')"><div class="modal-body"><div class="form-grid"><div><label>نوع الحركة</label><select class="field" name="kind"><option value="in">إضافة كمية</option><option value="out">صرف كمية</option><option value="waste">هالك</option></select></div><div><label>الكمية</label><input class="field" type="number" min=".01" step=".01" name="qty" required></div><div class="full"><label>سبب الحركة</label><input class="field" name="note" placeholder="مثال: صرف لمشروع..."></div></div><p>الرصيد الحالي: <b>${esc(x.qty)}</b> ${esc(x.unit||'')}</p></div><div class="modal-footer"><button class="btn btn-primary">حفظ الحركة</button></div></form>`;document.getElementById('modalBackdrop').classList.add('show');applyLocale();document.querySelectorAll('.quote-description-input').forEach(el=>{el.style.height='auto';el.style.height=el.scrollHeight+'px'})}
function applyStock(e,id){e.preventDefault();let fd=new FormData(e.target),x=db.inventory.find(x=>x.id===id),q=Number(fd.get('qty'));if(fd.get('kind')!=='in'&&q>Number(x.qty)){toast('الكمية المصروفة أكبر من المخزون');return}x.qty=Number(x.qty)+(fd.get('kind')==='in'?q:-q);x.note=(x.note||'')+` | حركة ${fd.get('kind')} ${q}: ${fd.get('note')||''}`;saveDB();closeModal();render();toast('تم تحديث المخزون')}
function payInvoice(id){let x=db.invoices.find(x=>x.id===id);if(!x)return;let amount=prompt(`المتبقي ${money(Math.max(0,x.total-x.paid))}\nأدخل مبلغ الدفعة:`);if(amount===null)return;let n=Number(amount);if(!Number.isFinite(n)||n<=0){toast('أدخل مبلغًا صحيحًا');return}x.paid=Math.min(x.total,Number(x.paid||0)+n);saveDB();render();toast('تم تسجيل الدفعة')}

function exportDocument(type,id){
 const isQuote=type==='quote', doc=(isQuote?db.quotes:db.invoices).find(x=>x.id===id);
 if(!doc){toast('تعذر العثور على المستند');return}
 const title=isQuote?'عرض سعر':'فاتورة', code=doc.code||'—', date=doc.date||'—', customer=customerName(doc.customerId)||'—';
 const rows=[];
 for(let n=1;n<100;n++){
  const tk=n===1?'title':`title${n}`, qk=n===1?'qty':`qty${n}`, pk=n===1?'unitPrice':`unitPrice${n}`;
  if(doc[tk]!==undefined||doc[qk]!==undefined||doc[pk]!==undefined){
   const desc=String(doc[tk]||'').trim(), qty=parseNumeric(doc[qk]), price=parseNumeric(doc[pk]);
   if(desc||qty||price) rows.push(`<tr><td>${rows.length+1}</td><td>${esc(desc||'—')}</td><td>${qty||''}</td><td>${price?money(price):''}</td><td>${qty&&price?money(qty*price):''}</td></tr>`);
  }
 }
 const subtotal=Number(doc.subtotal??(rows.reduce((sum,_,i)=>{const n=i+1,q=parseNumeric(doc[n===1?'qty':`qty${n}`]),p=parseNumeric(doc[n===1?'unitPrice':`unitPrice${n}`]);return sum+q*p},0)));
 const extra=parseNumeric(doc.extra), discount=parseNumeric(doc.discount), total=Number(doc.total||0), paid=parseNumeric(doc.paid), balance=Math.max(0,total-paid);
 const currency=esc(db.settings.currency||'ريال قطري');
 const summary=`<div class="summary"><div><span>المجموع</span><b>${money(subtotal)} ${currency}</b></div>${extra?`<div><span>تكاليف إضافية</span><b>${money(extra)} ${currency}</b></div>`:''}${discount?`<div><span>الخصم</span><b>${money(discount)} ${currency}</b></div>`:''}<div class="grand"><span>الإجمالي</span><b>${money(total)} ${currency}</b></div>${!isQuote?`<div><span>المدفوع</span><b>${money(paid)} ${currency}</b></div><div><span>المتبقي</span><b>${money(balance)} ${currency}</b></div>`:''}</div>`;
 const w=window.open('','_blank','width=900,height=700');
 if(!w){toast('اسمح بالنوافذ المنبثقة لتصدير PDF');return}
 w.document.write(`<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><title>${title} ${esc(code)}</title><style>
 @page{size:A4;margin:14mm}*{box-sizing:border-box}body{font-family:Tahoma,Arial,sans-serif;color:#20242a;margin:0;font-size:13px}
 .top{border-bottom:4px solid #762b3b;padding:0 0 14px;margin-bottom:22px;text-align:center}.en{direction:ltr;font-weight:bold;font-size:17px;letter-spacing:1px}.en-sub{direction:ltr;font-size:10px;margin-top:4px}.ar{font-size:20px;color:#762b3b;font-weight:bold;margin-top:10px}.ar-sub{font-size:12px;margin-top:3px}
 h1{text-align:center;color:#762b3b;font-size:22px;margin:22px 0}.meta{display:flex;justify-content:space-between;gap:20px;margin:20px 0}.meta div{line-height:2}.meta b{color:#762b3b}
 table{width:100%;border-collapse:collapse;margin-top:15px;page-break-inside:auto}thead{display:table-header-group}tr{page-break-inside:avoid}th{background:#762b3b;color:white}th,td{border:1px solid #c9c9c9;padding:10px;text-align:right}td:first-child,th:first-child{text-align:center;width:38px}
 .summary{width:48%;margin:18px 0 0 auto}.summary div{display:flex;justify-content:space-between;padding:7px 9px;border-bottom:1px solid #ddd}.summary .grand{background:#f4e9ec;color:#762b3b;font-size:16px;font-weight:bold;border:1px solid #762b3b}
 .notes{white-space:pre-wrap;margin-top:22px;border-top:1px solid #ddd;padding-top:12px;line-height:1.8}.footer{margin-top:35px;padding-top:10px;border-top:2px solid #762b3b;text-align:center;font-size:11px;line-height:1.8;color:#444}
 @media print{body{print-color-adjust:exact;-webkit-print-color-adjust:exact}}
 </style></head><body><header class="top"><div class="en">BO MANSOOR WORKS</div><div class="en-sub">FOR IRONWORK-ALUMINUM-UPVC.</div><div class="ar">${esc(db.settings.shopName||'ورشة بو منصور')}</div><div class="ar-sub">للحدادة والألمنيوم واليو بي في سي</div></header>
 <h1>${title}</h1><section class="meta"><div><div><b>رقم ${isQuote?'العرض':'الفاتورة'}:</b> ${esc(code)}</div><div><b>التاريخ:</b> ${esc(date)}</div></div><div><div><b>السيد / العميل:</b> ${esc(customer)}</div><div><b>الحالة:</b> ${esc(doc.status|| (isQuote?'مسودة':paid>=total?'مسدد':paid?'مدفوع جزئيًا':'غير مسدد'))}</div></div></section>
 <table><thead><tr><th>م</th><th>البيان / وصف العمل</th><th>العدد</th><th>السعر</th><th>الإجمالي</th></tr></thead><tbody>${rows.length?rows.join(''):'<tr><td colspan="5">لا توجد تفاصيل مسجلة</td></tr>'}</tbody></table>
 ${summary}${doc.note?`<div class="notes"><b>المواصفات والشروط:</b><br>${esc(doc.note)}</div>`:''}
 <footer class="footer">${isQuote?'* هذا العرض ساري لمدة أسبوع واحد فقط.':'شكراً لتعاملكم معنا'}<br>${esc(db.settings.phone||'5583 0254')}<br>${esc(db.settings.shopName||'ورشة بو منصور')}</footer>
 <script>window.onload=()=>setTimeout(()=>window.print(),300)<\/script></body></html>`);
 w.document.close();
}
function printDoc(title,body){let w=window.open('','_blank','width=900,height=700');if(!w){toast('اسمح بالنوافذ المنبثقة للطباعة');return}w.document.write(`<html lang="ar" dir="rtl"><head><meta charset="utf-8"><title>${esc(title)}</title><style>body{font-family:Tahoma,Arial;padding:35px;color:#182633}h1{font-size:23px}table{width:100%;border-collapse:collapse;margin-top:20px}td,th{border:1px solid #ddd;padding:10px;text-align:right}th{background:#f4f6f8}.muted{color:#777;font-size:12px}.total{font-size:20px;font-weight:bold;margin-top:20px}</style></head><body><h1>${esc(db.settings.shopName)}</h1><p>${esc(db.settings.phone||'')} ${esc(db.settings.address||'')}</p><hr><h2>${esc(title)}</h2>${body}<p class="muted">تم إنشاء المستند بواسطة ForgePro</p><script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close()}
function saveSettings(e){e.preventDefault();let fd=new FormData(e.target);db.settings={...db.settings,shopName:fd.get('shopName'),phone:fd.get('phone'),currency:fd.get('currency')||'ر.ق',address:fd.get('address'),tax:Number(fd.get('tax')||0),language:db.settings.language||'ar'};saveDB();render();toast('تم حفظ إعدادات الورشة')}
function exportBackup(){let blob=new Blob([JSON.stringify(db,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='ForgePro-Backup-'+dateNow()+'.json';a.click();URL.revokeObjectURL(a.href);toast('تم تجهيز النسخة الاحتياطية')}
function importBackup(){let f=document.getElementById('backupFile').files[0];if(!f){toast('اختر ملف النسخة الاحتياطية أولًا');return}if(!confirm('ستُستبدل البيانات الحالية بمحتويات النسخة. هل تريد المتابعة؟'))return;let r=new FileReader();r.onload=()=>{try{let obj=JSON.parse(r.result);if(!obj.customers||!obj.projects)throw new Error();db={...structuredClone(defaultDB),...obj};saveDB();render();toast('تمت استعادة النسخة بنجاح')}catch(e){toast('الملف غير صالح أو ليس نسخة ForgePro')}};r.readAsText(f)}
function exportCSV(collection){let arr=db[collection]||[];if(!arr.length){toast('لا توجد بيانات للتصدير');return}let keys=[...new Set(arr.flatMap(Object.keys))],csv=[keys.join(','),...arr.map(o=>keys.map(k=>'"'+String(o[k]??'').replace(/"/g,'""')+'"').join(','))].join('\r\n');let blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8;'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`ForgePro-${collection}-${dateNow()}.csv`;a.click();URL.revokeObjectURL(a.href)}
function resetData(){if(!confirm('تحذير: سيتم حذف كل العملاء والمشاريع والفواتير والمخزون نهائيًا من هذا المتصفح. هل أنت متأكد؟'))return;if(!confirm('تأكيد أخير: هل صدّرت نسخة احتياطية؟'))return;db=structuredClone(defaultDB);saveDB();render();toast('تمت إعادة ضبط البيانات')}
document.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>setPage(b.dataset.page)));
document.getElementById('mobileMenu').addEventListener('click',()=>document.getElementById('sidebar').classList.toggle('open'));
document.getElementById('quickAdd').addEventListener('click',()=>{const map={dashboard:'project',customers:'customer',projects:'project',quotes:'quote',production:'production',inventory:'inventory',purchases:'purchase',installations:'installation',invoices:'invoice',expenses:'expense'};openForm(map[currentPage]||'project')});
document.getElementById('modalBackdrop').addEventListener('click',e=>{if(e.target.id==='modalBackdrop')closeModal()});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
render();
